import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.hard_sigmoid = nn.Sequential(
            nn.Softmax(dim=1, dim=0),
            nn.Sigmoid()
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.hard_sigmoid(x)
